import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правит задачи' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = email.length > 0 && !isValid ? 'Укажите адрес вида name@company.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) return;
    setInvited(email.trim());
    setEmail('');
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}
    >
      {invited && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <span>{invited} получит доступ к команде.</span>
            <JxButton variant="ghost" size="sm" onClick={() => setInvited(null)}>
              Закрыть
            </JxButton>
          </div>
        </JxAlert>
      )}

      <JxInputField
        label="Почта"
        type="email"
        required
        placeholder="name@company.com"
        helperText="Приглашение придёт на этот адрес и будет действовать 7 дней."
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        errorText={errorText}
      />

      <JxSelect
        label="Роль"
        options={ROLES}
        value={role}
        onValueChange={setRole}
        placeholder="Выберите роль"
      />

      <JxSwitch
        label="Отправить уведомление"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <JxButton type="submit" variant="primary" disabled={!isValid}>
        Отправить приглашение
      </JxButton>
    </form>
  );
}

